import{_ as s,a0 as n,w as i,s as d,ao as l,I as o,a1 as r,A as p,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"6 個值得好好學習的 JavaScript 框架 | LCTT x X-CMD","titleTemplate":false,"description":"6 個值得好好學習的 JavaScript 框架 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"6 個值得好好學習的 JavaScript 框架 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"6 個值得好好學習的 JavaScript 框架 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20160707 6 Best JavaScript Frameworks to Learn In 2016","title":"6 個值得好好學習的 JavaScript 框架","tag":"201702","desc":""},"relativePath":"201702/20160707 6 Best JavaScript Frameworks to Learn In 2016.md","filePath":"[post].md"}'),m={name:"201702/20160707 6 Best JavaScript Frameworks to Learn In 2016.md"};function c(g,e,v,S,u,b){const t=n("Link");return i(),d("div",null,[e[15]||(e[15]=l('<h1 id="_6-個值得好好學習的-javascript-框架" tabindex="-1">6 個值得好好學習的 JavaScript 框架 <a class="header-anchor" href="#_6-個值得好好學習的-javascript-框架" aria-label="Permalink to “6 個值得好好學習的 JavaScript 框架”">​</a></h1><p><img src="https://discoversdkcdn.azureedge.net/postscontent/products/java.png" alt="值得好好學習的 6 個 JavaScript 框架"></p><p><strong>常言道，條條大路通羅馬，可是那一條適合我呢？</strong> 由於用於構建前端頁面等現代技術的出現，JavaScript 在 Web 開發社區早已是如雷貫耳。通過在網頁上編寫幾個函數並提供執行邏輯，可以很好的支持 HTML (主要是用於頁面的 <em>表現</em> 或者 <em>佈局</em>)。如果沒有 JavaScript，那頁面將沒有任何 <em>交互特性</em> 可言。</p><p>現在的框架和庫的已經從蠻荒時代崛起了，很多老舊的技術紛紛開始將功能分離成模組。現在不再需要在整個核心語言中支持所有特性了，開發者允許所有用户創建庫和框架來增強核心語言的功能。這樣，語言的靈活性獲得了了顯著提高。</p><p>如果在已經在使用 <strong>JavaScript</strong> (以及 <strong>JQuery</strong>) 來支持 HTML，那麼你肯定知道開發和維護一個大型應用需要付出多大的努力以及編寫多麼複雜的代碼，而 JavaScript 框架可以幫助你快速的構建交互式 Web 應用 (包含單頁面應用或者多頁面應用)。</p><p>當一個新手開發者想要學習 JavaScript 時，他常常會被各種 JavaScript 框架所吸引，也幸虧有為數眾多的社區，任何開發者都可以輕易地通過在線教程或者其他資源來學習。</p><p>但是，唉！多數的程序員都很難決定學習和使用哪一個框架。因此在本文中，我將為大家推薦 6 個值得好好學習的 JavaScript 框架。讓我們開始吧。</p><h3 id="_1、angularjs" tabindex="-1">1、AngularJS <a class="header-anchor" href="#_1、angularjs" aria-label="Permalink to “1、AngularJS”">​</a></h3><p><img src="https://discoversdkcdn.azureedge.net/postscontent/products/AngularJS_logo.svg.png" alt="Angular"></p><p><strong>(注：這是我個人最喜歡的框架)</strong></p><p>無論你是何時聽説的 JavaScript，很可能你早就聽過 AngularJS，因為這是在 JavaScript 社區中最為廣泛使用的框架了。它發佈於 2000 年，由 Google 開發 (這夠有説服力讓你是用了吧) ，它是一個開源項目，這意味着你可以閲讀、編輯和修改其源代碼以便更加符合自身的需求，並且不用向其開發者支付一分錢 (這不是很酷嗎？)。</p><p>如果説你覺得通過純粹的 JavaScript 代碼編寫一個複雜的 Web 應用比較困難的話，那麼你肯定會興奮的跳起來，因為它將顯著地減輕你的編碼負擔。它符合支持雙向數據綁定的 MVC (Model–view–controller，模型-視圖-控制) 設計典範。假如你不熟悉 MVC，你只需要知道它代表着無論何時探測到某些變化，它將自動更新前端 (比如，用户界面端) 和後端 (代碼或者服務器端) 數據。</p><p>MVC 可為大大減少構建複雜應用程序所需的時間和精力，所有你只需要集中精力於一處即可 (DOM 編程接口會自動同步更新視圖和模型)。由於 <em>視圖組件</em> 與 <em>模型組件</em> 是分離的，你可以很容易的創建一個可複用的組件，使得用户界面的效果非常好看。</p><p>如果因為某些原因，你已經使用了 <strong>TypeScript</strong> (一種與 JavaScript 非常相似的語言)，那麼你可以很容易就上手 AngularJS，因為這兩者的語法高度相似。與 <strong>TypeScript</strong> 相似這一特點在一定程度上提升了 AngularJS 的受歡迎程度。</p><p>目前，Angular 2.0 已經發布，並且提升了移動端的性能，這也足以向一個新的開發者證明，該框架的開發活躍的夠高並且定期更新。</p><p>AngularJS 有着大量的用户，包括 (但不限於) Udemy、Forbes、GoDaddy、Ford、NBA 和 Oscars。</p><p>對於那些想要一個高效的 MVC 框架，用來開發面面俱到、包含健壯且現代化的基礎架構的單頁應用的用户來説，我極力的推薦這個框架。這是第一個為無經驗 JavaScript 開發者設計的框架。</p><h3 id="_2、react" tabindex="-1">2、React <a class="header-anchor" href="#_2、react" aria-label="Permalink to “2、React”">​</a></h3><p><img src="https://discoversdkcdn.azureedge.net/postscontent/react%20%281%29.png" alt="React"></p><p>與 AngularJS 相似，React 也是一個 MVC (Model–view–controller，模型-視圖-控制) 類型的框架，但不同的是，它完全針對於 <em>視圖組件</em> (因為它是為 UI 特別定製的) 並且可與任何架構進行無縫銜接。這意味着你可以馬上將它運用到你的網站中去。</p><p>它從核心功能中抽象出 DOM 編程接口 (並且因此使用了虛擬 DOM)，所以你可以快速的渲染 UI，這使得你能夠通過 <em>node.js</em> 將它作為一個客户端框架來使用。它是由 Facebook 開發的開源項目，還有其它的開發者為它貢獻代碼。</p><p>假如説你見到過並喜歡 Facebook 和 Instagram 的界面，那麼你將會愛上 React。通過 React，你可以給你的應用的每個狀態設計一個簡單的視圖，當數據改變的時候，視圖也自動隨之改變。只要你想的話，可以創建各種的複雜 UI，也可以在任何應用中複用它。在服務器端，React 同樣支持通過 <em>node.js</em> 來進行渲染。對於其他的接口，React 也一樣表現得足夠的靈活。</p><p>除 Facebook 和 Instagram 外，還有好多公司也在使用 React，包括 Whatsapp、BBC、、PayPal、Netflix 和 Dropbox 等。</p><p>如果你只需要一個前端開發框架來構建一個非常複雜且界面極好的強大視圖層，那我極力向你推薦這個框架，但你需要有足夠的經驗來處理各種類型的 JavaScript 代碼，而且你再也不需要其他的組件了 (因為你可以自己集成它們)。</p><h3 id="_3、ember" tabindex="-1">3、Ember <a class="header-anchor" href="#_3、ember" aria-label="Permalink to “3、Ember”">​</a></h3><p><img src="https://discoversdkcdn.azureedge.net/postscontent/Ember.js_Logo_and_Mascot.png" alt="Ember"></p><p>這個 JavaScript 框架在 2011 年正式發佈，是由 <em>Yehuda Katz</em> 開發的開源項目。它有一個龐大且活躍的在線社區，所有在有任何問題時，你都可以在社區中提問。該框架吸收融合了非常多的通用 JavaScript 風格和經驗，以便確保開發者能最快的做到開箱即用。</p><p>它使用了 MVVM (Model–view–viewmodel，模型-視圖-視圖模型) 的設計模式，這使得它與 MVC 有些不一樣，因為它由一個 <em>連接器 (binder)</em> 幫助視圖和數據連接器進行通信。</p><p>對於 DOM 編程接口的快速服務端渲染，它藉助了 <em>Fastboot.js</em>，這能夠讓那些複雜 UI 的性能得到極大提高。</p><p>它的現代化路由模式和模型引擎還支持 <em>RESTful API</em>，這可以卻確保你可以使用這種最新的技術。它支持句柄集成模板（Handlebars integrated template），用以自動更新數據。</p><p>早在 2015 年間，它的風頭曾一度蓋過 AngularJS 和 React，被稱為最好的 JavaScript 框架，對於它在 JavaScript 社區中的可用性和吸引力，這樣的説服力該是足夠了的。</p><p>對於不追求高靈活性和大型架構的用户，並且僅僅只是為了趕赴工期、完成任務的話，我個人非常推薦這個 JavaScript 框架，</p><h3 id="_4、adonis" tabindex="-1">4、Adonis <a class="header-anchor" href="#_4、adonis" aria-label="Permalink to “4、Adonis”">​</a></h3><p><img src="https://discoversdkcdn.azureedge.net/postscontent/products/adonis.jpg" alt="Adonis"></p><p>如果你曾使用過 <em>Laravel</em> 和 <em>NodeJS</em>，那麼你在使用這一個框架之時會覺得相當順手，因為它是集合了這兩個平台的優點而形成的一個框架，對於任何種類的現代應用來説，它都顯得非常專業、圓潤和精緻。</p><p>它使用了 <em>NodeJS</em>，所以是一個很好的後端框架，同時還附帶有一些前端特性 (與前面提到那些更多地注重前端的框架不同)，所以想要進入後端開發的新手開發者會發覺這個框架相當迷人。</p><p>相比於 <em>NoSQL</em>，很多的開發者都比價喜歡使用 <em>SQL</em> 資料庫 (因為他們需要增強和數據以及其它特性的交互性)，這一現象在這個框架中得到了很好的體現，這時的它更接近標準，開發者也更容易使用。</p><p>如果你混跡於各類 PHP 社區，那你一定很熟悉 <strong>服務提供商 (Service Providers)</strong>，也由於 Adonis 相應的 PHP 風格包含其中，所以在使用它的時候，你會覺得似曾相識。</p><p>在它所有的特性中，最好的便是那個極為強大的路由引擎，支持使用函數來組織和管理應用的所有狀態、支持錯誤處理機制、支持通過 SQL ORM 來進行資料庫查詢、支持生成器、支持箭頭函數 (arrow functions)、支持代理等等。</p><p>如果喜歡使用無狀態 REST API 來構建服務器端應用，我比較推薦它，因為你會愛上這個框架的。</p><h3 id="_5、vue-js" tabindex="-1">5、Vue.js <a class="header-anchor" href="#_5、vue-js" aria-label="Permalink to “5、Vue.js”">​</a></h3><p><img src="https://discoversdkcdn.azureedge.net/postscontent/products/vuejs-logo.png" alt="Vue.js"></p><p>這一個開源的 JavaScript 框架，發佈於 2014 年，它有個極為簡單的 API，用以為現代 Web 界面（Modern Web Interface）開發交互式組件 (Reactive components)。其設計着重於簡單易用。與 Ember 相似，它使用的是 MVVM (Model–view–viewmodel，模型-視圖-視圖模型) 設計範例，這樣簡化了設計。</p><p>這個框架最有吸引力的一點是，你可以根據自身需求來選擇使用的模組。比如，你需要編寫簡單的 HTML 代碼，抓取 JSON，然後創建一個 Vue 實例來完成可以複用的小特效。</p><p>與之前的那些 JavaScript 框架相似，它使用雙路數據綁定來更新模型和視圖，同時也使用連接器來完成視圖和數據連接器的通信。這是一個還未完全成熟的框架，因為它全部的關注點都在視圖層，所以你需要自己處理其它的組件。</p><p>如果你熟悉 <em>AngularJS</em>，那你會感覺很順手，因為它大量嵌入了 <em>AngularJS</em> 的架構，如果你懂得 JavaScript 的基礎用法，那你的許多項目都可以輕易地遷移到該框架之下。</p><p>假如你只想把任務完成，或者想提升你自身的 JavaScript 編程經驗，又或者你需要學習不同的 JavAScript 框架的本質，我極力推薦這個。</p><h3 id="_6、backbone-js" tabindex="-1">6、Backbone.js <a class="header-anchor" href="#_6、backbone-js" aria-label="Permalink to “6、Backbone.js”">​</a></h3><p><img src="https://discoversdkcdn.azureedge.net/postscontent/products/backbonejs.png" alt="Backbone.JS"></p><p>這個框架可以很容易的集成到任何第三方的模板引擎，默認使用的是 <em>Underscore</em> 模板引擎，而且該框架僅有一個依賴 (<strong>JQuery</strong>)，因此它以輕量而聞名。它支持帶有 <strong>RESTful JSON</strong> 接口的 MVC (Model–view–controller，模型-視圖-控制) (可以自動更新前端和後端) 設計範例。</p><p>假如你曾經使用過著名的社交新聞網絡服務 <strong>reddit</strong>，那麼你肯定聽説過它在幾個單頁面應用中使用了 <strong>Backbone.js</strong>。<strong>Backbone.js</strong> 的原作者為之建立了與 <em>CoffeScript</em> 旗鼓相當的 <em>Underscore</em> 模板引擎，所以你可以放心，開發者知道該做什麼。</p><p>該框架在一個軟件包中提供了鍵值對 (key-value) 模型、視圖以及幾個打包的模組，所以你不需要額外下載其他的外部包，這樣可以節省不少時間。框架的源碼可以在 GitHub 進行查看，這意味着你可以根據需求進行深度定製。</p><p>如果你是尋找一個入門級框架來快速構建一個單頁面應用，那麼這個框架非常適合你。</p><h3 id="總而言之" tabindex="-1">總而言之 <a class="header-anchor" href="#總而言之" aria-label="Permalink to “總而言之”">​</a></h3><p>至此，我已經在本文着重説明了 6 個值得好好學習的 JavaScript 框架，希望你讀完本文後能夠決定使用哪個框架來完成自己的任務。</p><p>如果説對於選擇框架，你還是不知所措，請記住，這個世界是實踐出真知而非教條主義的。最好就是從列表中挑選一個來使用，看看最後是否滿足你的需求和興趣，如果還是不行，接着試試另一個。你也儘管放心好了，列表中的框架肯定是足夠了的。</p><hr><p>譯者簡介：</p>',58)),o("p",null,[r(t,{href:"http://GHLandy.com"},{default:p(()=>[...e[0]||(e[0]=[a("GHLandy",-1)])]),_:1}),e[1]||(e[1]=a(" —— 生活中所有歡樂與苦悶都應藏在心中，有些事兒註定無人知曉，自己也無從説起。",-1))]),e[16]||(e[16]=o("hr",null,null,-1)),o("p",null,[e[3]||(e[3]=a("via: ",-1)),r(t,{href:"http://www.discoversdk.com/blog/6-best-javascript-frameworks-to-learn-in-2016"},{default:p(()=>[...e[2]||(e[2]=[a("http://www.discoversdk.com/blog/6-best-javascript-frameworks-to-learn-in-2016",-1)])]),_:1})]),o("p",null,[e[7]||(e[7]=a("作者：",-1)),r(t,{href:"http://www.discoversdk.com/blog/6-best-javascript-frameworks-to-learn-in-2016"},{default:p(()=>[...e[4]||(e[4]=[a("Danyal Zia",-1)])]),_:1}),e[8]||(e[8]=a(" 譯者：",-1)),r(t,{href:"https://github.com/GHLandy"},{default:p(()=>[...e[5]||(e[5]=[a("GHLandy",-1)])]),_:1}),e[9]||(e[9]=a(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:p(()=>[...e[6]||(e[6]=[a("wxy",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=a("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[10]||(e[10]=[a("LCTT",-1)])]),_:1}),e[13]||(e[13]=a(" 原創編譯，",-1)),r(t,{href:"https://linux.cn/"},{default:p(()=>[...e[11]||(e[11]=[a("Linux中國",-1)])]),_:1}),e[14]||(e[14]=a(" 榮譽推出",-1))])])}const k=s(m,[["render",c]]);export{h as __pageData,k as default};
